# PBS Kids Educational Activities
import requests

PBS_API_KEY = "aHR0cHM6Ly9tN2xpYi5kZXYvYXBpL2xpdmVfc3RyZWFtcy92MS9nZXRfc3RyZWFtLnBocD9pZD0"
BASE_URL = "https://api.pbskids.org/v1"

def get_activities(age_group, topic):
    """Get educational activities by age and topic"""
    response = requests.get(
        f"{BASE_URL}/activities",
        params={
            "age": age_group,
            "topic": topic,
            "api_key": PBS_API_KEY
        }
    )
    return response.json()

def get_games(age_group):
    """Get educational games for kids"""
    response = requests.get(
        f"{BASE_URL}/games",
        params={
            "age": age_group,
            "api_key": PBS_API_KEY
        }
    )
    return response.json()
